package screen

import (
	"bytes"
	"embed"
	"encoding/json"
	"image"
	"image/color"
	"image/draw"
	"image/png"
	"strings"
)

// Glyph atlases are generated by tools/fontgen from the OFL fonts in this
// folder (Silkscreen, VT323). Blitting 1-bit atlases keeps the display free
// of any font-rendering dependency and every glyph pixel-exact.
//
//go:embed fonts/*.png fonts/*.json
var fontFS embed.FS

type font struct {
	atlas  *image.Gray
	height int
	glyphs map[rune][2]int // x offset in atlas, advance
}

var (
	silk16  = mustFont("silk16")
	silk24b = mustFont("silk24b")
	vt20    = mustFont("vt20")
)

func mustFont(name string) *font {
	pb, err := fontFS.ReadFile("fonts/" + name + ".png")
	if err != nil {
		panic(err)
	}
	img, err := png.Decode(bytes.NewReader(pb))
	if err != nil {
		panic(err)
	}
	gray := image.NewGray(img.Bounds())
	draw.Draw(gray, gray.Bounds(), img, image.Point{}, draw.Src)

	jb, err := fontFS.ReadFile("fonts/" + name + ".json")
	if err != nil {
		panic(err)
	}
	var meta struct {
		Height int               `json:"height"`
		Glyphs map[string][2]int `json:"glyphs"`
	}
	if err := json.Unmarshal(jb, &meta); err != nil {
		panic(err)
	}
	f := &font{atlas: gray, height: meta.Height, glyphs: map[rune][2]int{}}
	for k, v := range meta.Glyphs {
		for _, r := range k {
			f.glyphs[r] = v
		}
	}
	return f
}

func (f *font) glyph(r rune) [2]int {
	if g, ok := f.glyphs[r]; ok {
		return g
	}
	return f.glyphs['?']
}

// width of s with extra letter spacing after each glyph but the last.
func (f *font) width(s string, spacing int) int {
	w, n := 0, 0
	for _, r := range s {
		w += f.glyph(r)[1]
		n++
	}
	if n > 1 {
		w += spacing * (n - 1)
	}
	return w
}

// draw writes s with its top-left corner at (x, y) and returns the width.
func (f *font) draw(dst *image.RGBA, x, y int, s string, c color.RGBA, spacing int) int {
	x0 := x
	for _, r := range s {
		g := f.glyph(r)
		for gy := 0; gy < f.height; gy++ {
			for gx := 0; gx < g[1]; gx++ {
				if f.atlas.GrayAt(g[0]+gx, gy).Y > 127 {
					setPx(dst, x+gx, y+gy, c)
				}
			}
		}
		x += g[1] + spacing
	}
	return x - x0 - spacing
}

// drawScaled is draw with every glyph pixel enlarged k times (big digits).
func (f *font) drawScaled(dst *image.RGBA, x, y int, s string, c color.RGBA, spacing, k int) int {
	x0 := x
	for _, r := range s {
		g := f.glyph(r)
		for gy := 0; gy < f.height; gy++ {
			for gx := 0; gx < g[1]; gx++ {
				if f.atlas.GrayAt(g[0]+gx, gy).Y > 127 {
					fill(dst, image.Rect(x+gx*k, y+gy*k, x+gx*k+k, y+gy*k+k), c)
				}
			}
		}
		x += g[1]*k + spacing
	}
	return x - x0 - spacing
}

// fit shortens s with an ellipsis so it is at most max pixels wide.
func (f *font) fit(s string, max int) string {
	if f.width(s, 0) <= max {
		return s
	}
	rs := []rune(s)
	for len(rs) > 0 {
		rs = rs[:len(rs)-1]
		t := strings.TrimRight(string(rs), " ") + "…"
		if f.width(t, 0) <= max {
			return t
		}
	}
	return ""
}
